package cryptokit

import (
	"bytes"
	"encoding/hex"
	"errors"
	"testing"
	"time"

	"golang.org/x/crypto/argon2"
)

func TestArgon2idPHCReferenceVector(t *testing.T) {
	// Generated by the reference PHC Argon2 CLI and also carried by the
	// upstream x/crypto test suite: Argon2id v1.3, t=1, m=64 KiB, p=1.
	want, err := hex.DecodeString("655ad15eac652dc59f7170a7332bf49b8469be1fdb9c28bb")
	if err != nil {
		t.Fatal(err)
	}
	got := argon2.IDKey([]byte("password"), []byte("somesalt"), 1, 64, 1, uint32(len(want)))
	defer wipe(got)
	if !bytes.Equal(got, want) {
		t.Fatalf("Argon2id reference vector = %x, want %x", got, want)
	}
}

func TestArgon2CalibrationChoosesHighestP95WithinTarget(t *testing.T) {
	policy := Argon2CalibrationPolicy{
		TargetP95: 800 * time.Millisecond,
		MemoryKiB: MinArgon2MemoryKiB,
		Lanes:     1,
		Samples:   3,
	}
	calls := 0
	result, err := calibrateArgon2id(policy, func(params Argon2Params) (time.Duration, error) {
		calls++
		base := time.Duration(params.Iterations) * 250 * time.Millisecond
		return base + time.Duration(calls%3)*time.Millisecond, nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.Params.Iterations != 3 || !result.WithinTarget ||
		result.MeasuredP95 < 750*time.Millisecond || result.MeasuredP95 > policy.TargetP95 {
		t.Fatalf("calibration result = %#v", result)
	}
	if calls != 12 {
		t.Fatalf("measure calls = %d, want 12", calls)
	}
}

func TestArgon2CalibrationRetainsMinimumWhenTargetCannotBeMet(t *testing.T) {
	policy := Argon2CalibrationPolicy{
		TargetP95: 500 * time.Millisecond,
		MemoryKiB: MinArgon2MemoryKiB,
		Lanes:     1,
		Samples:   3,
	}
	result, err := calibrateArgon2id(policy, func(Argon2Params) (time.Duration, error) {
		return 700 * time.Millisecond, nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.Params.Iterations != MinArgon2Iterations || result.WithinTarget {
		t.Fatalf("minimum fallback = %#v", result)
	}
}

func TestArgon2CalibrationRejectsInvalidPolicyAndMeasurements(t *testing.T) {
	valid := Argon2CalibrationPolicy{
		TargetP95: time.Second,
		MemoryKiB: MinArgon2MemoryKiB,
		Lanes:     1,
		Samples:   3,
	}
	tests := []Argon2CalibrationPolicy{
		{TargetP95: time.Millisecond, MemoryKiB: MinArgon2MemoryKiB, Lanes: 1, Samples: 3},
		{TargetP95: time.Second, MemoryKiB: MinArgon2MemoryKiB - 1, Lanes: 1, Samples: 3},
		{TargetP95: time.Second, MemoryKiB: MinArgon2MemoryKiB, Lanes: 0, Samples: 3},
		{TargetP95: time.Second, MemoryKiB: MinArgon2MemoryKiB, Lanes: 1, Samples: 2},
	}
	for _, policy := range tests {
		if _, err := calibrateArgon2id(policy, func(Argon2Params) (time.Duration, error) {
			return time.Second, nil
		}); !errors.Is(err, ErrArgon2Calibration) {
			t.Fatalf("invalid policy %#v = %v", policy, err)
		}
	}
	if _, err := calibrateArgon2id(valid, func(Argon2Params) (time.Duration, error) {
		return 0, nil
	}); !errors.Is(err, ErrArgon2Calibration) {
		t.Fatalf("zero measurement = %v", err)
	}
	if _, err := calibrateArgon2id(valid, func(Argon2Params) (time.Duration, error) {
		return 0, errors.New("timer failed")
	}); !errors.Is(err, ErrArgon2Calibration) {
		t.Fatalf("measurement error = %v", err)
	}
}
